from __future__ import annotations

import asyncio
import sys
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

# Make the repo root importable when running from a source checkout.
_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from actor_factory.runner import ActorRunConfig, PPEScraperRunner  # noqa: E402

MARKET_TYPES = ("h2h", "spreads", "totals")


async def _guarded(coro: Any) -> Any:
    """Await a data call; a failure degrades to None, never kills the run."""
    try:
        return await coro
    except Exception:  # noqa: BLE001 - per-section degradation by design
        return None


def _best_odds(odds_events: list[dict[str, Any]], market_types: list[str]) -> dict[str, Any]:
    """Reduce multi-book odds events to the best price per side per market."""
    best: dict[str, Any] = {}
    for event in odds_events:
        for market in market_types:
            bookmakers = event.get("bookmakers") or []
            for book in bookmakers:
                for bet in book.get("bets") or []:
                    if bet.get("market") != market:
                        continue
                    for value in bet.get("values") or []:
                        side = str(
                            value.get("handicap")
                            or value.get("point")
                            or value.get("key")
                            or "main"
                        )
                        price = value.get("odd")
                        if not isinstance(price, (int, float)):
                            continue
                        entry = {"book": book.get("book"), "price": price}
                        slot = best.setdefault(market, {})
                        if side not in slot or price > slot[side].get("price", 0):
                            slot[side] = entry
    return best


class OddsComparisonRunner(PPEScraperRunner):
    """Runner that maps one URL to an odds-comparison report."""

    async def process_url(self, url: str, options: dict[str, Any]) -> dict[str, Any]:
        from pry.api.routers.data.sports_data import (
            sports_arbitrage,
            sports_books,
            sports_odds,
            sports_plus_ev,
        )

        sport = options.get("sport", "all") or "all"
        market_types = options.get("market_types") or list(MARKET_TYPES)
        market_types = [m for m in market_types if m in MARKET_TYPES] or list(MARKET_TYPES)

        item: dict[str, Any] = {
            "url": url,
            "status": "ok",
            "sport": sport,
            "scraped_at": datetime.now(UTC).isoformat(),
        }

        # Live odds + books registry are the base layer.
        odds_task = _guarded(sports_odds(event_query="", sport=sport, limit=50))
        books_task = _guarded(sports_books(sport=sport, market="h2h", limit=50))
        odds_res, _books_res = await asyncio.gather(odds_task, books_task)
        odds_events = (odds_res or {}).get("data", [])
        item["best_odds"] = _best_odds(odds_events, market_types)

        first_event = odds_events[0] if odds_events else {}
        item["event_id"] = first_event.get("id") or first_event.get("event_id") or ""
        item["event_name"] = first_event.get("name") or first_event.get("event_name") or ""
        item["commence_time"] = first_event.get("commence_time") or ""

        # Arbitrage detection across books.
        if options.get("include_arbitrage", True):
            arb_res = await _guarded(sports_arbitrage(sport=sport, min_yield_pct=0.5))
            item["arbitrage_opportunities"] = (arb_res or {}).get("data", [])
        else:
            item["arbitrage_opportunities"] = []

        # +EV opportunities vs the sharp book.
        if options.get("include_ev", True):
            ev_res = await _guarded(sports_plus_ev(sharp_book="pinnacle", min_ev_pct=1.0))
            item["ev_opportunities"] = (ev_res or {}).get("data", [])
        else:
            item["ev_opportunities"] = []

        # Line movement history is best-effort: the historical module may not
        # have landed yet; degrade to an empty history.
        item["line_movements"] = []

        item["metadata"] = {
            "domain": url.split("/")[2] if "://" in url else url,
            "sport": sport,
            "market_types": market_types,
        }
        return item


async def main() -> None:
    runner = OddsComparisonRunner(
        config=ActorRunConfig(
            primary_event="odds-comparison-pulled",
            default_output_format="markdown",
            processor_name="jsondata",
        ),
        actor_module=None,  # resolved lazily so tests can inject a mock
    )
    await runner.run()


if __name__ == "__main__":
    asyncio.run(main())
